PRAGMA foreign_keys=ON;
BEGIN;
CREATE TABLE departments (department_id INTEGER NOT NULL PRIMARY KEY, name VARCHAR(100) NOT NULL);
CREATE TABLE employees (employee_id INTEGER NOT NULL PRIMARY KEY, department_id INTEGER NOT NULL, manager_id INTEGER, name VARCHAR(100) NOT NULL, email VARCHAR(160) NOT NULL UNIQUE, salary DECIMAL(18,2) NOT NULL, notes VARCHAR(400), CONSTRAINT fk_employee_department FOREIGN KEY(department_id) REFERENCES departments(department_id), CONSTRAINT fk_employee_manager FOREIGN KEY(manager_id) REFERENCES employees(employee_id));
CREATE TABLE customers (customer_id INTEGER NOT NULL PRIMARY KEY, customer_code VARCHAR(20) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, region VARCHAR(20) NOT NULL, email VARCHAR(160));
CREATE TABLE products (product_id INTEGER NOT NULL PRIMARY KEY, sku VARCHAR(20) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, unit_price DECIMAL(18,2) NOT NULL, active INTEGER NOT NULL);
CREATE TABLE orders (order_id INTEGER NOT NULL PRIMARY KEY, customer_id INTEGER NOT NULL, sales_rep_id INTEGER NOT NULL, ordered_on DATE NOT NULL, status VARCHAR(20) NOT NULL, total_amount DECIMAL(18,2) NOT NULL, note VARCHAR(400), CONSTRAINT fk_order_customer FOREIGN KEY(customer_id) REFERENCES customers(customer_id), CONSTRAINT fk_order_employee FOREIGN KEY(sales_rep_id) REFERENCES employees(employee_id));
CREATE TABLE order_items (order_id INTEGER NOT NULL, line_no INTEGER NOT NULL, product_id INTEGER NOT NULL, quantity INTEGER NOT NULL, unit_price DECIMAL(18,2) NOT NULL, CONSTRAINT pk_order_items PRIMARY KEY(order_id,line_no), CONSTRAINT fk_item_order FOREIGN KEY(order_id) REFERENCES orders(order_id), CONSTRAINT fk_item_product FOREIGN KEY(product_id) REFERENCES products(product_id));
CREATE TABLE support_tickets (ticket_id INTEGER NOT NULL PRIMARY KEY, customer_code VARCHAR(20) NOT NULL, subject VARCHAR(200) NOT NULL, priority INTEGER NOT NULL);
CREATE TABLE exact_values (value_id INTEGER NOT NULL PRIMARY KEY, big_integer BIGINT NOT NULL, amount TEXT NOT NULL, optional_text VARCHAR(200));
CREATE TABLE demo_ready (id INTEGER NOT NULL PRIMARY KEY, dataset_version VARCHAR(40) NOT NULL);
CREATE INDEX ix_orders_customer_date ON orders(customer_id,ordered_on);
CREATE INDEX ix_orders_status ON orders(status);
CREATE INDEX ix_items_product ON order_items(product_id);
CREATE INDEX ix_employee_department ON employees(department_id);
CREATE INDEX ix_ticket_customer_code ON support_tickets(customer_code);
